Here is the commit message:
fuse: missing copy_finish in fuse-over-io-uring argument
 copies

Fix a possible reference count leak of payload pages during
fuse argument copies.

[Joanne: simplified error cleanup]

Fixes: c090c8abae4b ("fuse: Add io-uring sqe commit and fetch support")
Cc: stable@vger.kernel.org # v6.14
Signed-off-by: Cheng Ding <cding@ddn.com>
Signed-off-by: Bernd Schubert <bschubert@ddn.com>
Reviewed-by: Joanne Koong <joannelkoong@gmail.com>
Signed-off-by: Miklos Szeredi <mszeredi@redhat.com>

Here is the root cause:
In fuse-over-io-uring, the functions `fuse_uring_copy_from_ring` and `fuse_uring_args_to_ring` in `dev_uring.c` failed to call `fuse_copy_finish()` after performing argument copies via `fuse_copy_out_args` or `fuse_copy_args`. This omitted cleanup of the copy state, specifically the unmapping and putting of payload pages held in the current buffer, resulting in a reference count leak. The leak occurs because each successful copy acquires a page reference that must be released explicitly; without `fuse_copy_finish`, those references are never dropped.

Here is the patch:

 static int fuse_uring_copy_from_ring(struct fuse_ring *ring,
 				     struct fuse_req *req,
 				     struct fuse_ring_ent *ent)
 {
 	struct fuse_copy_state cs;
 	struct fuse_args *args = req->args;
 	struct iov_iter iter;
 	int err;
 	struct fuse_uring_ent_in_out ring_in_out;

 	err = copy_from_user(&ring_in_out, &ent->headers->ring_ent_in_out,
 			     sizeof(ring_in_out));
 	if (err)
 		return -EFAULT;

 	err = import_ubuf(ITER_SOURCE, ent->payload, ring->max_payload_sz,
 			  &iter);
 	if (err)
 		return err;

 	fuse_copy_init(&cs, false, &iter);
 	cs.is_uring = true;
 	cs.req = req;

-	return fuse_copy_out_args(&cs, args, ring_in_out.payload_sz);
+	err = fuse_copy_out_args(&cs, args, ring_in_out.payload_sz);
+	fuse_copy_finish(&cs);
+	return err;
 }

   */
 static int fuse_uring_args_to_ring(struct fuse_ring *ring, struct fuse_req *req,
 				   struct fuse_ring_ent *ent)
 {
 	struct fuse_copy_state cs;
 	struct fuse_args *args = req->args;
 	struct fuse_in_arg *in_args = args->in_args;
 	int num_args = args->in_numargs;
 	int err;
 	struct iov_iter iter;
 	struct fuse_uring_ent_in_out ent_in_out = {
 		.flags = 0,
 		.commit_id = req->in.h.unique,
 	};

 	err = import_ubuf(ITER_DEST, ent->payload, ring->max_payload_sz, &iter);
 	if (err) {
 		pr_info_ratelimited("fuse: Import of user buffer failed\n");
 		return err;
 	}

 	fuse_copy_init(&cs, true, &iter);
 	cs.is_uring = true;
 	cs.req = req;

 	if (num_args > 0) {
 		/*
 		 * Expectation is that the first argument is the per op header.
 		 * Some op code have that as zero size.
 		 */
 		if (args->in_args[0].size > 0) {
 			err = copy_to_user(&ent->headers->op_in, in_args->value,
 					   in_args->size);
 			if (err) {
 				pr_info_ratelimited(
 					"Copying the header failed.\n");
 				return -EFAULT;
 			}
 		}
 		in_args++;
 		num_args--;
 	}

 	/* copy the payload */
 	err = fuse_copy_args(&cs, num_args, args->in_pages,
 			     (struct fuse_arg *)in_args, 0);
+	fuse_copy_finish(&cs);
 	if (err) {
 		pr_info_ratelimited("%s fuse_copy_args failed\n", __func__);
 		return err;
 	}

 	ent_in_out.payload_sz = cs.ring.copied_sz;
 	err = copy_to_user(&ent->headers->ring_ent_in_out, &ent_in_out,
 			   sizeof(ent_in_out));
 	return err ? -EFAULT : 0;
 }



